def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = 0
    d_opp = 0
    for i in range(n):
        if opp_at(i) == 'C':
            c_opp += 1
        else:
            d_opp += 1

    if d_opp == 0:
        return 'C'
    if c_opp == 0:
        return 'D'

    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    last = opp_at(n - 1)
    coop_rate = c_opp / n
    remaining = 100 - n

    recent_start = n - 12
    if recent_start < 0:
        recent_start = 0
    recent_c = 0
    recent_d = 0
    for i in range(recent_start, n):
        if opp_at(i) == 'C':
            recent_c += 1
        else:
            recent_d += 1
    recent_len = n - recent_start
    recent_coop = recent_c / recent_len

    mirror_score = 0
    if n >= 4:
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                mirror_score += 1
        mirror_rate = mirror_score / (n - 1)
    else:
        mirror_rate = 0.0

    if remaining <= 3:
        if coop_rate > 0.55 and streak_d == 0:
            return 'D'
        if streak_d >= 1 and coop_rate < 0.5:
            return 'D'
        if coop_rate >= 0.7:
            return 'D'
        if last == 'D':
            return 'D'
        return 'C'

    if remaining <= 7:
        if coop_rate > 0.6 and streak_d == 0:
            return 'D'
        if coop_rate > 0.8:
            return 'D'
        if streak_d >= 2:
            return 'D'
        return 'C'

    if streak_d >= 3:
        return 'D'

    if streak_d == 2:
        if coop_rate > 0.75 and recent_coop > 0.6:
            return 'D'
        return 'D'

    if streak_d == 1:
        if coop_rate > 0.8 and streak_c >= 4:
            return 'C'
        if coop_rate > 0.65 and recent_coop > 0.7:
            return 'C'
        if n >= 4 and opp_at(n - 2) == 'C' and opp_at(n - 3) == 'C':
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    if coop_rate >= 0.9 and streak_c >= 6:
        if n > 20 and n % 19 == 0:
            return 'D'
        return 'C'

    if coop_rate >= 0.75:
        if mirror_rate > 0.75 and n >= 5:
            return me_at(n - 1)
        return 'C'

    if mirror_rate >= 0.8 and n >= 6:
        if coop_rate > 0.5:
            return me_at(n - 1)
        if last == 'C':
            return 'C'
        return 'D'

    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                alt_score += 1
        if alt_score >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    if recent_coop >= 0.85 and coop_rate > 0.6:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    if coop_rate > 0.6 and last == 'D' and streak_d == 1:
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    if coop_rate > 0.5 and recent_coop > 0.5:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    if coop_rate > 0.4:
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    return 'D'
